def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally recent and overall behavior.
    opp_d = 0
    my_d = 0
    cc = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1
        if a == 'C' and b == 'C':
            cc += 1

    # Recent window (last 12 rounds) for responsiveness.
    start = n - 12
    if start < 0:
        start = 0
    rec_len = n - start
    rec_opp_d = 0
    rec_opp_c = 0
    rec_cc = 0
    for i in range(start, n):
        a, b = history[i]
        if b == 'D':
            rec_opp_d += 1
        else:
            rec_opp_c += 1
        if a == 'C' and b == 'C':
            rec_cc += 1
    rec_mutual = rec_cc / rec_len

    last_opp = history[-1][1]
    last_my = history[-1][0]

    # Endgame: squeeze the last rounds, unless opponent is a reliable cooperator.
    remaining = 100 - n
    if remaining <= 2:
        if opp_d * 10 <= n and last_opp == 'C':
            return 'C'
        return 'D'
    if remaining <= 6:
        if opp_d * 5 <= n:
            return 'D'
        if last_opp == 'C' and last_my == 'D':
            return 'C'
        return 'D'

    # Against a nearly pure cooperator: defect steadily to exploit, but keep
    # enough cooperation so we do not disturb their willingness to cooperate.
    if n >= 12 and opp_d * 12 <= n:
        # If they have ever punished us recently, back off briefly.
        if rec_opp_d >= 2:
            return 'C'
        # Sustained exploitation with occasional cooperative cover.
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Against a nearly pure defector: defect, with rare probes.
    if n >= 10 and opp_d * 10 >= n * 9:
        if last_opp == 'C' and last_my == 'D':
            return 'C'
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # Build cooperation early: forgive a single defection, but punish repeats.
    if n < 10:
        if opp_d == 0:
            return 'C'
        if last_opp == 'D' and my_d == 0:
            return 'D'
        if last_opp == 'D' and last_my == 'D':
            return 'C'
        return 'C'

    # Moderate defectors: retaliate firmly but return to cooperation quickly.
    opp_rate = opp_d / n
    if opp_rate <= 0.2:
        if last_opp == 'D':
            # Forgive a lone defection if recent cooperation is strong.
            if rec_opp_d <= 1 and rec_mutual >= 0.6:
                return 'C'
            return 'D'
        if last_my == 'D' and rec_opp_c >= 3:
            return 'C'
        return 'C'

    if opp_rate <= 0.45:
        if last_opp == 'D':
            if rec_opp_d >= 3:
                return 'D'
            if rec_mutual >= 0.7 and rec_opp_d == 1:
                return 'C'
            return 'D'
        # Opponent cooperated; keep cooperating if we also have.
        if last_my == 'D' and rec_opp_d <= 1:
            return 'C'
        return 'C'

    # Aggressive opponent: punish heavily, but try limited cooperative restarts.
    if opp_rate <= 0.7:
        if last_opp == 'C':
            if rec_opp_c >= 3:
                return 'C'
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        # Facing D.
        if last_my == 'D' and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent defects almost always.
    if last_opp == 'C' and rec_opp_c >= 2:
        return 'C'
    if rng.random() < 0.05:
        return 'C'
    return 'D'
